export interface Database {
  countUsers(): Promise<number>
  close(): Promise<void>
}

export function countUsers(db: Database): Promise<number> {
  return db.countUsers()
}

export async function createDatabase(): Promise<Database> {
  let users = ['Alice', 'Bob', 'Carol']
  let closed = false
  return {
    async countUsers() {
      if (closed) throw new Error('database is closed')
      return users.length
    },
    async close() {
      closed = true
      users = []
    },
  }
}

export function add(a: number, b: number): number {
  return a + b
}

export interface Server {
  request(path: string): Promise<number>
  stop(): Promise<void>
}

export function request(server: Server, path: string): Promise<number> {
  return server.request(path)
}

export async function startServer(): Promise<Server> {
  let running = true
  return {
    async request(path) {
      if (!running) throw new Error('server is stopped')
      return path === '/users' ? 200 : 404
    },
    async stop() {
      running = false
    },
  }
}

