export function countFenceLines(lines: readonly string[]): number {
  let count = 0
  for (const line of lines) if (line.startsWith('```')) count++
  return count
}

export function directoryOf(path: string): string {
  const index = path.lastIndexOf('/')
  return index < 0 ? '' : path.slice(0, index)
}

export function findCodeBlocks(lines: readonly string[]): readonly CodeBlock[] {
  const blocks: CodeBlock[] = []
  let open = -1
  let info = ''
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]
    if (!line.startsWith('```')) continue
    if (open < 0) {
      open = index
      info = line.slice(3).trim()
    } else {
      blocks.push({ info, open, close: index })
      open = -1
      info = ''
    }
  }
  if (open >= 0) blocks.push({ info, open, close: -1 })
  return blocks
}

export function findLinks(text: string): readonly LinkReference[] {
  const references: LinkReference[] = []
  let index = text.indexOf('](')
  while (index >= 0) {
    const end = text.indexOf(')', index + 2)
    if (end < 0) break
    if (end > index + 2) {
      references.push({ link: text.slice(index + 2, end), line: lineOfIndex(text, index) })
      index = text.indexOf('](', end + 1)
    } else index = text.indexOf('](', index + 1)
  }
  return references
}

export function findMalformedRows(text: string): readonly TableRow[] {
  const malformed: TableRow[] = []
  let width: number | undefined
  const lines = splitLines(stripCodeSpans(text))
  for (let index = 0; index < lines.length; index++) {
    const row = lines[index]
    if (!row.startsWith('|')) {
      width = undefined
      continue
    }
    const columns = row.split(/(?<!\\)\|/).length
    if (width === undefined) width = columns
    else if (columns !== width) malformed.push({ row, line: index + 1 })
  }
  return malformed
}

export function findRelativeImports(text: string): readonly string[] {
  const specifiers: string[] = []
  for (const line of splitLines(text)) {
    for (const quote of ["'", '"']) {
      let index = line.indexOf(quote)
      while (index >= 0) {
        const end = line.indexOf(quote, index + 1)
        if (end < 0) break
        const specifier = line.slice(index + 1, end)
        if (specifier.startsWith('./') || specifier.startsWith('../')) specifiers.push(specifier)
        index = line.indexOf(quote, end + 1)
      }
    }
  }
  return specifiers
}

export function headings(text: string): readonly string[] {
  const found: string[] = []
  for (const line of splitLines(text)) {
    let hashes = 0
    while (hashes < line.length && line[hashes] === '#') hashes++
    if (hashes === 0 || line[hashes] !== ' ') continue
    const heading = line.slice(hashes + 1)
    if (heading.length > 0) found.push(heading)
  }
  return found
}

export function isCodeLanguage(info: string): boolean {
  const space = info.search(/\s/)
  const language = space < 0 ? info : info.slice(0, space)
  for (const candidate of codeLanguages) if (candidate === language) return true
  return false
}

function isNoneMarker(body: string): boolean {
  if (body === 'none') return true
  if (!body.startsWith('none')) return false
  const separator = body[4]
  return separator === ' ' || separator === '\t' || separator === '—' || separator === '-'
}

export function isSourceLine(line: string): boolean {
  return line.startsWith(sourcePrefix)
}

export function lineOfIndex(text: string, index: number): number {
  return text.slice(0, index).split('\n').length
}

export function normalizeNewlines(text: string): string {
  return text.replaceAll('
', '
').replaceAll('', '
')
}

export function parseMarker(line: string): Marker | undefined {
  const trimmed = line.trim()
  if (!trimmed.startsWith(markerPrefix) || !trimmed.endsWith(markerSuffix)) return undefined
  const body = trimmed.slice(markerPrefix.length, trimmed.length - markerSuffix.length).trim()
  if (body === '') return { kind: 'invalid', reason: 'marker has no example reference' }
  if (isNoneMarker(body)) return parseNoneMarker(body)
  const hash = body.indexOf('#')
  const target = hash < 0 ? body : body.slice(0, hash)
  const region = hash < 0 ? undefined : body.slice(hash + 1)
  if (target === '') return { kind: 'invalid', reason: 'marker has no example path' }
  if (region !== undefined && region === '') return { kind: 'invalid', reason: 'marker has an empty region name' }
  return { kind: 'example', target, region }
}

function parseNoneMarker(body: string): Marker {
  const rest = body.slice(4).trimStart()
  // 区切りは全角ダッシュでもハイフンでもよいが、理由は必須。
  if (!rest.startsWith('—') && !rest.startsWith('-')) return { kind: 'invalid', reason: 'none marker needs a reason' }
  const reason = rest.slice(1).trim()
  if (reason === '') return { kind: 'invalid', reason: 'none marker needs a reason' }
  return { kind: 'none', reason }
}

export function relativeFrom(baseDirectory: string, target: string): string {
  const from = baseDirectory === '' ? [] : baseDirectory.split('/')
  const to = target.split('/')
  let shared = 0
  while (shared < from.length && shared < to.length - 1 && from[shared] === to[shared]) shared++
  const up = from.slice(shared).map(() => '..')
  return [...up, ...to.slice(shared)].join('/')
}

export function resolvePath(baseDirectory: string, relative: string): string | undefined {
  if (relative.startsWith('/')) return undefined
  const segments = baseDirectory === '' ? [] : baseDirectory.split('/')
  for (const segment of relative.split('/')) {
    if (segment === '' || segment === '.') continue
    if (segment === '..') {
      if (segments.length === 0) return undefined
      segments.pop()
      continue
    }
    segments.push(segment)
  }
  // リポジトリ直下そのものを指す参照（`..` など）は '.' として扱う。
  if (segments.length === 0) return '.'
  return segments.join('/')
}

export function slug(heading: string): string {
  let slugged = ''
  for (const character of heading.toLowerCase()) {
    const code = character.codePointAt(0) ?? 0
    if (code >= 0x80 || /[\w\- ]/.test(character)) slugged += character
  }
  return slugged.replaceAll(' ', '-')
}

export function sourceLine(document: string, target: string): string {
  return `${sourcePrefix}[${target}](${relativeFrom(directoryOf(document), target)})`
}

export function splitLines(text: string): readonly string[] {
  return text.split('\n')
}

export function stripCodeSpans(text: string): string {
  let stripped = ''
  let index = 0
  for (;;) {
    const start = text.indexOf('```', index)
    if (start < 0) break
    const end = text.indexOf('```', start + 3)
    if (end < 0) break
    stripped += text.slice(index, start)
    stripped += '\n'.repeat(text.slice(start, end + 3).split('\n').length - 1)
    index = end + 3
  }
  return stripped + text.slice(index)
}

export type RegionParse = {
  readonly lines: readonly string[]
  readonly regions: ReadonlyMap<string, Region>
  readonly markers: ReadonlySet<number>
  readonly issues: readonly RegionIssue[]
}

export type RegionParse = {
  readonly lines: readonly string[]
  readonly regions: ReadonlyMap<string, Region>
  readonly markers: ReadonlySet<number>
  readonly issues: readonly RegionIssue[]
}

function dedent(lines: readonly string[]): readonly string[] {
  let minimum = -1
  for (const line of lines) {
    if (line.trim() === '') continue
    const indent = line.length - line.trimStart().length
    if (minimum < 0 || indent < minimum) minimum = indent
  }
  if (minimum <= 0) return lines
  return lines.map((line) => (line.trim() === '' ? '' : line.slice(minimum)))
}

export function isRegionName(name: string): boolean {
  return /^[a-z0-9-]+$/.test(name)
}

function markerName(trimmed: string, keyword: string): string | undefined {
  if (!trimmed.startsWith(keyword)) return undefined
  const rest = trimmed.slice(keyword.length)
  if (rest !== '' && !rest.startsWith(' ') && !rest.startsWith('\t')) return undefined
  return rest.trim()
}

export function parseRegions(text: string): RegionParse {
  const lines = splitLines(normalizeNewlines(text))
  const regions = new Map<string, Region>()
  const markers = new Set<number>()
  const issues: RegionIssue[] = []
  const open: { name: string; start: number; valid: boolean }[] = []
  for (let index = 0; index < lines.length; index++) {
    const trimmed = lines[index].trim()
    const closing = markerName(trimmed, endKeyword)
    if (closing !== undefined) {
      markers.add(index)
      const current = open.pop()
      if (current === undefined || current.name !== closing) {
        issues.push({ kind: 'mismatched-endregion', name: closing, line: index + 1 })
        // 対応が取れないので開いていた範囲は捨て、以降の行を素直に読み進める。
        if (current !== undefined) issues.push({ kind: 'unclosed-region', name: current.name, line: current.start + 1 })
        continue
      }
      if (!current.valid) continue
      const region = { name: current.name, start: current.start, end: index }
      regions.set(current.name, region)
      if (renderLines(lines, markers, current.start + 1, index) === '')
        issues.push({ kind: 'empty-region', name: current.name, line: current.start + 1 })
      continue
    }
    const opening = markerName(trimmed, startKeyword)
    if (opening === undefined) continue
    markers.add(index)
    if (!isRegionName(opening)) {
      issues.push({ kind: 'invalid-region-name', name: opening, line: index + 1 })
      open.push({ name: opening, start: index, valid: false })
      continue
    }
    const duplicate = regions.has(opening) || open.some((entry) => entry.name === opening)
    if (duplicate) issues.push({ kind: 'duplicate-region', name: opening, line: index + 1 })
    open.push({ name: opening, start: index, valid: !duplicate })
  }
  for (const entry of open) issues.push({ kind: 'unclosed-region', name: entry.name, line: entry.start + 1 })
  return { lines, regions, markers, issues }
}

export function renderFile(parse: RegionParse): string {
  const body: string[] = []
  for (let index = 0; index < parse.lines.length; index++) if (!parse.markers.has(index)) body.push(parse.lines[index])
  return body.join('\n').trim()
}

function renderLines(lines: readonly string[], markers: ReadonlySet<number>, from: number, to: number): string {
  const body: string[] = []
  for (let index = from; index < to; index++) if (!markers.has(index)) body.push(lines[index])
  return trimBlankEdges(dedent(body)).join('\n')
}

export function renderRegion(parse: RegionParse, region: Region): string {
  return renderLines(parse.lines, parse.markers, region.start + 1, region.end)
}

function trimBlankEdges(lines: readonly string[]): readonly string[] {
  let start = 0
  let end = lines.length
  while (start < end && lines[start].trim() === '') start++
  while (end > start && lines[end - 1].trim() === '') end--
  return lines.slice(start, end)
}

export const configSchema = v.object({
  vite: v.optional(v.looseObject({})),
  projects: v.optional(
    v.record(
      v.string(),
      v.object({
        include: v.array(v.string()),
        exclude: v.optional(v.array(v.string())),
      }),
    ),
  ),
  reporter: v.optional(v.picklist(['pretty', 'json'])),
  collectionTimeout: v.optional(v.number()),
  shutdownGrace: v.optional(v.number()),
})

export async function collectWithin<T>(log: CollectionLog, load: () => Promise<T>): Promise<T> {
  if (openLog) throw new TypeError('a collection scope is already open')
  openLog = log
  try {
    return await load()
  } finally {
    openLog = null
  }
}

export function recordCollectionEvent(event: CollectionEvent): void {
  openLog?.append(event)
}

export type CliMessage =
  | { type: 'loading'; file: string; timeout: number }
  | { type: 'running'; reporter: Reporter; shutdownGrace: number }
  | { type: 'progress'; progress: Progress }
  | { type: 'timeout'; result: MutableRunResult }
  | ({ type: 'deadline' } & Deadline)
  | { type: 'result'; result: MutableRunResult; reporter: Reporter }
