export interface TestSource {
  file: string
  projects: string[]
}

export function nodeSources(nodes: readonly ExecutionNode[], sources: readonly TestSource[]): readonly TestSource[] {
  return nodes.map((node) => sources[node.rootIndex])
}

export function withSources(result: MutableRunResult, byNode: readonly TestSource[]): MutableRunResult {
  return { ...result, tests: result.tests.map((node) => ({ ...node, source: byNode[node.path[0]] })) }
}

export type CollectionEvent =
  | { kind: 'declared'; definition: object; origin: SourceLocation }
  | { kind: 'consumed'; definition: object }
  | { kind: 'registered'; definition: RuntimeDefinitionHandle; origin: SourceLocation }

export type CollectionEvent =
  | { kind: 'declared'; definition: object; origin: SourceLocation }
  | { kind: 'consumed'; definition: object }
  | { kind: 'registered'; definition: RuntimeDefinitionHandle; origin: SourceLocation }

export class CollectionLog {
  readonly #events: CollectionEvent[] = []
  append(event: CollectionEvent): void {
    this.#events.push(event)
  }
  registrationsIn(file: string): RegisteredTest[] {
    return registrationsOf(this.#events, file)
  }
  unregisteredDefinitions(files: ReadonlySet<string>): SourceLocation[] {
    return unregisteredOf(this.#events, files)
  }
}

registrationsIn(file: string): RegisteredTest[] {
    return registrationsOf(this.#events, file)
  }

unregisteredDefinitions(files: ReadonlySet<string>): SourceLocation[] {
    return unregisteredOf(this.#events, files)
  }

function registrationsOf(events: readonly CollectionEvent[], file: string): RegisteredTest[] {
  return events.flatMap((event) => (event.kind === 'registered' && event.origin.file === file ? [event] : []))
}

function unregisteredOf(events: readonly CollectionEvent[], files: ReadonlySet<string>): SourceLocation[] {
  const declared = new Map<object, SourceLocation>()
  const used = new Set<object>()
  for (const event of events)
    if (event.kind === 'declared') declared.set(event.definition, event.origin)
    else used.add(event.definition)
  return [...declared].flatMap(([definition, origin]) =>
    files.has(origin.file) && !used.has(definition) ? [origin] : [],
  )
}

export interface SelectedFile {
  file: string
  projects: string[]
}

export function selectFiles(
  config: Config,
  request: CollectionRequest,
  { resolve, glob }: ProjectFiles,
): SelectedFile[] {
  if (request.files.length)
    return [...new Set(request.files.map((file) => resolve(file)))].sort().map((file) => ({ file, projects: [] }))
  if (config.projects) {
    const selected = new Map<string, SelectedFile>()
    const names = [...new Set(request.options.projects ?? Object.keys(config.projects))]
    for (const name of names) {
      if (!Object.hasOwn(config.projects, name)) throw new TypeError(`unknown project: ${name}`)
      const { include, exclude = [] } = config.projects[name]
      const excluded = new Set(exclude.flatMap((pattern) => [...glob(pattern)].map((file) => resolve(file))))
      for (const pattern of include) {
        for (const match of glob(pattern)) {
          const file = resolve(match)
          if (excluded.has(file)) continue
          const entry = selected.get(file) ?? { file, projects: [] }
          if (!entry.projects.includes(name)) entry.projects.push(name)
          selected.set(file, entry)
        }
      }
    }
    return [...selected.values()].sort((a, b) => a.file.localeCompare(b.file))
  }
  if (request.options.projects?.length) throw new TypeError(`unknown project: ${request.options.projects[0]}`)
  const include = ['**/*.{test,spec}.ts']
  const exclude = ['**/node_modules/**', '**/dist/**']
  const files = new Set(include.flatMap((pattern) => [...glob(pattern)]))
  for (const pattern of exclude) for (const file of glob(pattern)) files.delete(file)
  return [...files]
    .map((file) => resolve(file))
    .sort()
    .map((file) => ({ file, projects: [] }))
}

interface Collected {
  definitions: RuntimeDefinitionHandle[]
  roots: RootReference[]
  sources: TestSource[]
}

interface CollectionLimits {
  timeout: number
  shutdownGrace: number
  reporter: Reporter
}

@Injectable()
export class CollectionSession {
  readonly #files: ProjectFiles
  readonly #modules: ModuleToolchain
  readonly #warnings: Warnings
  readonly #events: CollectionEvents
  readonly #executor: ExecutionLauncher
  readonly #walker: RunWalker
  readonly #snapshot: RunSnapshot

  constructor(
    files = inject(ProjectFiles),
    modules = inject(ModuleToolchain),
    warnings = inject(Warnings),
    events = inject(CollectionEvents),
    executor = inject(ExecutionLauncher),
    walker = inject(RunWalker),
    snapshot = inject(RunSnapshot),
  ) {
    this.#files = files
    this.#modules = modules
    this.#warnings = warnings
    this.#events = events
    this.#executor = executor
    this.#walker = walker
    this.#snapshot = snapshot
  }

  async run(request: CollectionRequest, signal: AbortSignal): Promise<void> {
    // どのファイルを読んでいる途中で落ちたかは、失敗の文脈として外側のcatchから見えなければならない。
    const collecting: { file: SelectedFile | null } = { file: null }
    try {
      // 設定はcompilerより先に要る。vite設定を知らないままtest runtimeを立てられない。
      const config = await this.#loadConfig(request.options)
      const limits = collectionLimits(request.options, config)
      const files = this.#select(request, config)
      const execution = this.#executor.open()
      let modules: ModuleSession | undefined
      try {
        this.#events.loading('test runtime setup', limits.timeout)
        modules = await this.#modules.open(config.vite)
        const collected = await this.#collect(modules, files, limits.timeout, collecting)
        await this.#execute(execution, modules, this.#plan(modules, collected, request), limits, signal)
      } finally {
        // 変換要求が届かなくなってからcompilerを閉じる。compiler起動の失敗時もworkerは残さない。
        try {
          await execution.close()
        } finally {
          await modules?.close()
        }
      }
    } catch (error) {
      const context = collecting.file
        ? `while collecting ${this.#files.relative(collecting.file.file)}${projectsOf(collecting.file.projects)}: `
        : ''
      this.#events.error(context + errorStack(error))
    }
  }

  /**
   * 設定ファイルの読み込み自体にも期限がある。設定はまだ読めていないため、引数の指定か既定値だけで測る。
   * 設定が決まってからの期限はcollectionLimitsが測り直す。
   */
  #loadConfig(options: CliOptions): Promise<Config> {
    const timeout = options.collectionTimeout ?? 30_000
    positive(timeout, 'collectionTimeout')
    return this.#files.readConfig(options, (file) => this.#events.loading(file, timeout))
  }

  #select(request: CollectionRequest, config: Config): SelectedFile[] {
    const files = selectFiles(config, request, this.#files)
    if (!files.length) throw new TypeError('no test files matched')
    return files
  }

  /** 読み込みはCollectionLogを開いた間だけ記録される。読み込み順が登録順で、実行側もその順に突き合わせる。 */
  async #collect(
    modules: ModuleSession,
    files: SelectedFile[],
    timeout: number,
    collecting: { file: SelectedFile | null },
  ): Promise<Collected> {
    const log = new CollectionLog()
    const definitions: RuntimeDefinitionHandle[] = [],
      roots: RootReference[] = [],
      sources: TestSource[] = [],
      collected = new Set<object>()
    await collectWithin(log, async () => {
      for (const { file, projects } of files) {
        collecting.file = { file, projects }
        this.#events.loading(file, timeout)
        await modules.import(file)
        const registered = log.registrationsIn(file)
        if (!registered.length)
          throw new TypeError(`no tests registered in ${this.#files.relative(file)}${projectsOf(projects)}`)
        for (const [index, entry] of registered.entries()) {
          const definition = entry.definition
          if (collected.has(definition))
            throw new TypeError(
              `duplicate root definition: ${this.#files.relative(file)}:${entry.origin.line}${projectsOf(projects)}`,
            )
          collected.add(definition)
          definitions.push(definition)
          roots.push({ file, index, origin: entry.origin })
          sources.push({ file: this.#files.relative(file), projects })
        }
      }
    })
    collecting.file = null
    for (const origin of log.unregisteredDefinitions(new Set(files.map(({ file }) => file))))
      this.#warnings.warn(
        `hanamaru: unregistered test definition: ${this.#files.relative(origin.file)}:${origin.line}:${origin.column}\n`,
      )
    return { definitions, roots, sources }
  }

  #plan(modules: ModuleSession, { definitions, roots, sources }: Collected, request: CollectionRequest): Planned {
    const settings: RunSettings = {
      forbidOnly: request.options.ci,
      failOnFlaky: request.options.failOnFlaky,
      filter: request.options.filter,
    }
    const blueprints: RuntimeBlueprint[] = validatedBlueprints(definitions)
    const plan = createPlan(blueprints, settings)
    return {
      plan,
      settings,
      sources: nodeSources(plan.allNodes, sources),
      spec: {
        roots,
        preparation: modules.prepare(blueprints),
        shape: JSON.stringify(modules.describe(plan.allNodes)),
      },
    }
  }

  async #execute(
    prepared: PreparedExecution,
    modules: ModuleSession,
    { plan, settings, spec, sources }: Planned,
    limits: CollectionLimits,
    signal: AbortSignal,
  ) {
    // 1回のrunの通知は収集のprotocolへ出す。出どころを付けられるのは計画が組み上がったこの時点から。
    const events = new CollectionRunEvents(this.#events, sources, this.#snapshot)
    const execution = await prepared.start(events, spec, {
      invoke: (name, args) => modules.invoke(name, args),
      signal,
      onLoading: (file) => this.#events.loading(file, limits.timeout),
    })
    this.#events.running(limits.reporter, limits.shutdownGrace)
    let result
    try {
      // 重なりの錠は走査より先に取る。読み込んだテストファイルから始まったrunも重なりとして弾く。
      result = await runExclusively(() => this.#walker.run(execution, () => plan, settings, events, signal))
    } finally {
      await execution.close()
    }
    this.#events.result(withSources(result, sources), limits.reporter)
  }
}

