interface Planned {
  plan: Plan
  settings: RunSettings
  spec: ExecutionSpec
  sources: readonly TestSource[]
}

function collectionLimits(options: CollectionRequest['options'], config: Config): CollectionLimits {
  const timeout = options.collectionTimeout ?? config.collectionTimeout ?? 30_000
  const shutdownGrace = options.shutdownGrace ?? config.shutdownGrace ?? 1_000
  positive(timeout, 'collectionTimeout')
  positive(shutdownGrace, 'shutdownGrace')
  const reporter = options.reporter ?? config.reporter ?? 'pretty'
  if (reporter !== 'pretty' && reporter !== 'json') throw new TypeError('reporter must be pretty or json')
  return { timeout, shutdownGrace, reporter }
}

function projectsOf(projects: string[]): string {
  return projects.length ? ` (projects: ${projects.join(', ')})` : ''
}

export function callReference(condition: RuntimeCallAssertion, index: number): AssertionReference {
  return { index, source: 'expectCalls', subject: 'call', key: condition.key, matcher: condition.check.matcher }
}

function checkCalls(condition: ResolvedCallAssertion, history: Value[][], { equal }: Comparison) {
  const c = condition.check
  switch (c.matcher) {
    case 'calledTimes':
      return history.length === c.count
    case 'notCalled':
      return history.length === 0
    case 'calledWith':
      return history.some((args) => equal(args, c.args))
    case 'calledOnceWith':
      return history.length === 1 && equal(history[0], c.args)
    case 'calledNthWith':
      return history.length >= c.n && equal(history[c.n - 1], c.args)
  }
  return false
}

function checkCondition(condition: RuntimeValueAssertion, actual: Value, { equal, matchObject }: Comparison) {
  const c = condition.check
  switch (c.matcher) {
    case 'toBe':
      return Object.is(actual, c.expected)
    case 'toEqual':
      return equal(actual, c.expected)
    case 'toMatchObject':
      return matchObject(actual, c.expected)
    case 'toSatisfy': {
      const result = invoke(c.predicate, undefined, [actual])
      if (result && typeof property(Object(result), 'then') === 'function')
        throw new TypeError('toSatisfy predicate must be synchronous')
      return result === true
    }
    case 'toBeInstanceOf':
      return actual instanceof functionValue(c.ctor)
    case 'toThrow':
      if (!(actual instanceof Error)) return false
      return typeof c.message === 'string'
        ? actual.message.includes(c.message)
        : new RegExp(c.message.source, c.message.flags).test(actual.message)
  }
  return false
}

export function evaluate(
  item: Omit<RuntimeCase, 'calls'> & { calls: readonly ResolvedCallAssertion[] },
  ctx: Readonly<Fields>,
  outcome: TargetOutcome,
  rawValue: Value,
  records: Map<object, Map<string, Value[][]>>,
  comparison: Comparison,
): { failures: Failure[]; assertions: AssertionResult[] } {
  const failures: Failure[] = [],
    assertions: AssertionResult[] = []
  let expected: readonly RuntimeValueAssertion[] = []
  if (item.expect) {
    try {
      expected = arrayValue(invoke(item.expect.build, undefined, [ctx])).map(checkedAssertion)
      if (
        !expected.length ||
        expected.some((x) => !validateAssertion(x) || !['result', 'error'].includes(x.subject)) ||
        new Set(expected.map((x) => x.subject)).size !== 1
      )
        throw new TypeError('expect must return nonempty result-only or error-only assertions')
    } catch (error) {
      failures.push(failure('execution', 'expect', 'expect failed', { cause: diagnostic(error) }))
      expected = []
    }
  }
  const wanted = expected[0]?.subject === 'error' ? 'throw' : 'return'
  if (outcome.kind !== wanted)
    failures.push(failure('outcome', 'target', 'unexpected target outcome', { expected: wanted, actual: outcome }))
  for (const [index, condition] of expected.entries()) {
    const ref = expectationReference(condition, index)
    if (outcome.kind !== wanted) {
      assertions.push({ assertion: ref, status: 'not-evaluated', reason: 'target outcome mismatch' })
      continue
    }
    try {
      const matches = checkCondition(condition, rawValue, comparison)
      const okay = condition.negated === true ? !matches : matches
      const expectedValue = snapshotExpected(condition),
        actualValue = diagnostic(rawValue)
      assertions.push({
        assertion: ref,
        status: okay ? 'passed' : 'failed',
        expected: expectedValue,
        actual: actualValue,
      })
      if (!okay)
        failures.push(
          failure('assertion', 'assertion', 'expectation did not match', {
            assertion: ref,
            expected: expectedValue,
            actual: actualValue,
          }),
        )
    } catch (error) {
      failures.push(
        failure('execution', 'assertion', 'expectation threw', { cause: diagnostic(error), assertion: ref }),
      )
      assertions.push({
        assertion: ref,
        status: 'failed',
        expected: snapshotExpected(condition),
        actual: diagnostic(rawValue),
      })
    }
  }
  for (const [index, condition] of item.calls.entries()) {
    const ref = callReference(condition, index)
    const history = records.get(condition.object)?.get(condition.key) ?? []
    try {
      const okay = checkCalls(condition, history, comparison)
      const expectedValue = snapshotExpected(condition),
        actualValue = snapshotCalls(condition, history)
      assertions.push({
        assertion: ref,
        status: okay ? 'passed' : 'failed',
        expected: expectedValue,
        actual: actualValue,
      })
      if (!okay)
        failures.push(
          failure('assertion', 'assertion', 'call expectation did not match', {
            assertion: ref,
            expected: expectedValue,
            actual: actualValue,
          }),
        )
    } catch (error) {
      failures.push(
        failure('execution', 'assertion', 'call expectation threw', { cause: diagnostic(error), assertion: ref }),
      )
      assertions.push({
        assertion: ref,
        status: 'failed',
        expected: snapshotExpected(condition),
        actual: snapshotCalls(condition, history),
      })
    }
  }
  return { failures, assertions }
}

function expectationReference(condition: RuntimeValueAssertion, index: number): AssertionReference {
  return v.parse(assertionReferenceSchema, {
    index,
    source: 'expect',
    subject: condition.subject,
    ...(condition.negated === true ? { negated: true } : {}),
    matcher: condition.check.matcher,
  })
}

export function failure<K extends Failure['kind']>(
  kind: K,
  phase: Extract<Failure, { kind: K }>['phase'],
  message: string,
  more: Omit<Extract<Failure, { kind: K }>, 'kind' | 'phase' | 'message'>,
): Failure {
  return v.parse(failureSchema, { kind, phase, message, ...more })
}

export function faultToFailure<T>(input: T, phase: ExecutionPhase = 'middleware'): Failure {
  const error = valueOf(input)
  if (error instanceof MiddlewareFault)
    return error.kind === 'timeout'
      ? failure('timeout', phase, error.message, {
          timeoutMs: required(error.timeoutMs),
          cleanup: 'complete',
          ...(error.stage === 'contract' ? {} : { stage: error.stage }),
        })
      : failure('execution', phase, error.message, { cause: diagnostic(error.cause) })
  return failure('execution', phase, errorMessage(error), { cause: diagnostic(error) })
}

function snapshotCalls(condition: ResolvedCallAssertion, history: Value[][]) {
  switch (condition.check.matcher) {
    case 'calledTimes':
    case 'notCalled':
      return diagnostic(history.length)
    case 'calledOnceWith':
      return diagnostic({ count: history.length, calls: history })
    case 'calledNthWith':
      return diagnostic({ count: history.length, args: history[condition.check.n - 1] ?? null })
    case 'calledWith':
      return diagnostic(history)
  }
}

function snapshotExpected(condition: RuntimeAssertion) {
  const check = condition.check
  if ('expected' in check) return diagnostic(check.expected)
  if (check.matcher === 'calledOnceWith') return diagnostic({ count: 1, args: check.args })
  if (check.matcher === 'calledNthWith') return diagnostic({ n: check.n, args: check.args })
  if ('args' in check) return diagnostic(check.args)
  if ('count' in check) return diagnostic(check.count)
  if (check.matcher === 'notCalled') return diagnostic(0)
  if ('message' in check) return diagnostic(check.message)
  if ('ctor' in check) return diagnostic(check.ctor)
  if ('predicate' in check) return diagnostic(check.predicate)
  throw new TypeError('invalid assertion diagnostic')
}

@Injectable()
export class AttemptExecutor {
  readonly #comparison: Comparison
  readonly #tracker: RunTracker

  constructor(comparison = inject(Comparison), tracker = inject(RunTracker)) {
    this.#comparison = comparison
    this.#tracker = tracker
  }

  async execute(
    node: SuiteNode,
    item: RuntimeCase,
    number: number,
    calls: CallBinder,
    events: RunEvents,
  ): Promise<AttemptReply> {
    const tracker = this.#tracker
    const config = configWith(node.config, item.config)
    const started = now()
    const record: AttemptRecord = {
      outcome: null,
      failures: [],
      assertions: [],
      cleanup: 'complete',
      retryable: true,
    }
    const timer = new StageTimer<ExecutionPhase>(config.timeout, 'middleware', (phase) => {
      tracker.markPhase(phase)
      tracker.abort('timeout')
      events.timedOut()
    })
    const core = async (ctx: Readonly<Fields>) => {
      if (timer.expired()) return
      timer.enter('instrumentation')
      const resolvedCalls = item.calls.map((condition): ResolvedCallAssertion => {
        const object = condition.object ?? objectValue(invoke(condition.objectFrom, undefined, [ctx]))
        if (condition.objectFrom && property(object, Symbol.toStringTag) === 'Module')
          throw new TypeError('call.from requires a fixture object; use call(namespace, key) for modules')
        const check = condition.check
        const resolved =
          'argsFrom' in check ? { ...check, args: arrayValue(invoke(check.argsFrom, undefined, [ctx])) } : check
        return calls.bind({ ...condition, object, check: resolved })
      })
      const instruments = new MethodPatch(overlayMocks(node.mocks, item.mocks), resolvedCalls, node.bp.target)
      let failed = false,
        originalError
      try {
        timer.enter('args')
        const args =
          item.args.kind === 'calls'
            ? []
            : item.args.kind === 'value'
              ? item.args.value
              : arrayValue(invoke(item.args.build, undefined, [ctx]))
        if (!Array.isArray(args)) throw new TypeError('argsFrom must return an array')
        timer.enter('target')
        let rawValue
        let outcomeKind: TargetOutcome['kind'] = 'return'
        if (item.args.kind === 'calls') {
          rawValue = (
            await executeInvocations(item.args, node.bp.target, () => !timer.expired() && tracker.reason === null)
          ).value
        } else
          try {
            const target = node.bp.target
            if (target.kind === 'relation') throw new TypeError('relation cases require calls()')
            rawValue = valueOf(
              await (target.kind === 'method'
                ? invoke(methodValue(target.object, target.key), target.object, args)
                : invoke(target.fn, undefined, args)),
            )
          } catch (error) {
            rawValue = valueOf(error)
            outcomeKind = 'throw'
          }
        instruments.stopRecording()
        const outcome: TargetOutcome = { kind: outcomeKind, value: diagnostic(rawValue) }
        record.outcome = outcome
        timer.enter('expect')
        const evaluated = evaluate(
          { ...item, calls: resolvedCalls },
          ctx,
          outcome,
          rawValue,
          instruments.records,
          this.#comparison,
        )
        record.failures.push(...evaluated.failures)
        record.assertions.push(...evaluated.assertions)
        if (record.failures.length) throw new CaseFailed()
      } catch (error) {
        failed = true
        originalError = valueOf(error)
      }
      timer.enter('cleanup')
      const errors = instruments.restore()
      if (errors.length) throw new CleanupFault(failed ? [originalError, ...errors] : errors)
      if (failed) throw originalError
    }
    const runFrame = async (index: number, ctx: Fields): Promise<void> => {
      if (timer.expired()) return
      if (index === node.frames.length) return core(Object.freeze(ctx))
      const frame = node.frames[index]
      const walkSteps = async (stepIndex: number, current: Fields): Promise<void> => {
        if (stepIndex === frame.steps.length) return runFrame(index + 1, { ...current, ...frame.fields })
        return withMiddleware(
          frame.steps[stepIndex],
          Object.freeze(current),
          (fields) => walkSteps(stepIndex + 1, { ...current, ...fields }),
          () => events.timedOut(),
        )
      }
      return walkSteps(0, ctx)
    }
    try {
      await runFrame(0, {})
    } catch (error) {
      const fault = classifyAttemptError(valueOf(error), timer.stage)
      record.failures.push(...fault.failures)
      record.cleanup = fault.cleanup
      record.retryable = fault.retryable
      // タイムアウトはrunを打ち切る理由として強く、後処理の失敗で上書きしない。
      if (fault.abort && tracker.reason !== 'timeout') tracker.abort(fault.abort)
    } finally {
      timer.clear()
    }
    const overdue = timer.overdue()
    if (overdue) {
      tracker.abort('timeout')
      record.failures.push(
        failure('timeout', overdue.stage, `attempt exceeded ${config.timeout}ms`, {
          timeoutMs: config.timeout,
          cleanup: record.cleanup,
        }),
      )
    }
    if (record.failures.some((x) => x.kind === 'timeout')) tracker.abort('timeout')
    return {
      result: finalizeAttempt(record, item.calls, number, now() - started, tracker.reason),
      retryable: record.retryable,
    }
  }
}

