@Injectable()
export class RunTracker {
  #reason: Reason | null = null
  #active: ActiveExecution | null = null
  #phase: ExecutionPhase | null = null

  get reason(): Reason | null {
    return this.#reason
  }
  get active(): ActiveExecution | null {
    return this.#active
  }
  get phase(): ExecutionPhase | null {
    return this.#phase
  }

  abort(reason: Reason): void {
    this.#reason = reason
  }
  /** 中断はタイムアウトを上書きしない。 */
  interrupt(): void {
    if (this.#reason !== 'timeout') this.#reason = 'interrupted'
  }
  begin(active: ActiveExecution): void {
    this.#active = active
    this.#phase = active.kind === 'attempt' ? 'middleware' : null
  }
  markPhase(phase: ExecutionPhase): void {
    this.#phase = phase
  }
  end(): void {
    this.#active = null
    this.#phase = null
  }
  activeProgress(reason: Reason): Progress {
    return progressOf(required(this.#active, 'no active execution for progress'), this.#phase, reason)
  }
}

get active(): ActiveExecution | null {
    return this.#active
  }

activeProgress(reason: Reason): Progress {
    return progressOf(required(this.#active, 'no active execution for progress'), this.#phase, reason)
  }

begin(active: ActiveExecution): void {
    this.#active = active
    this.#phase = active.kind === 'attempt' ? 'middleware' : null
  }

end(): void {
    this.#active = null
    this.#phase = null
  }

get phase(): ExecutionPhase | null {
    return this.#phase
  }

get reason(): Reason | null {
    return this.#reason
  }

export class StageTimer<S> {
  readonly #timeoutMs: number
  readonly #onExpire: (stage: S) => void
  #stage: S
  #startedAt: number | null
  #expired: S | null = null
  #handle: ReturnType<typeof setTimeout> | undefined

  constructor(timeoutMs: number, stage: S, onExpire: (stage: S) => void) {
    this.#timeoutMs = timeoutMs
    this.#onExpire = onExpire
    this.#stage = stage
    this.#startedAt = now()
    this.#schedule()
  }

  #schedule(): void {
    this.#handle = setTimeout(() => {
      this.#expired = this.#stage
      this.#onExpire(this.#stage)
    }, this.#timeoutMs)
  }

  get stage(): S {
    return this.#stage
  }

  /** 期限は据え置いたまま区間だけを進める。 */
  enter(stage: S): void {
    this.#stage = stage
  }

  /** 新しい区間として期限を測り直す。 */
  restart(stage: S): void {
    this.clear()
    this.#stage = stage
    this.#expired = null
    this.#startedAt = now()
    this.#schedule()
  }

  /** 期限の対象外の区間へ入る。発火済みの記録は残す。 */
  pause(stage: S): void {
    this.clear()
    this.#stage = stage
    this.#startedAt = null
  }

  /** タイマーを止める。期限切れの判定材料は残すため、止めたあとでも結果を読める。 */
  clear(): void {
    clearTimeout(this.#handle)
    this.#handle = undefined
  }

  /** 発火済みなら、発火した時点の区間。 */
  expired(): { stage: S } | null {
    return this.#expired === null ? null : { stage: this.#expired }
  }

  /** 発火済み、または計測中の区間が期限を過ぎているなら、その区間。 */
  overdue(): { stage: S } | null {
    if (this.#expired !== null) return { stage: this.#expired }
    if (this.#startedAt !== null && now() - this.#startedAt > this.#timeoutMs) return { stage: this.#stage }
    return null
  }
}

#schedule(): void {
    this.#handle = setTimeout(() => {
      this.#expired = this.#stage
      this.#onExpire(this.#stage)
    }, this.#timeoutMs)
  }

expired(): { stage: S } | null {
    return this.#expired === null ? null : { stage: this.#expired }
  }

overdue(): { stage: S } | null {
    if (this.#expired !== null) return { stage: this.#expired }
    if (this.#startedAt !== null && now() - this.#startedAt > this.#timeoutMs) return { stage: this.#stage }
    return null
  }

pause(stage: S): void {
    this.clear()
    this.#stage = stage
    this.#startedAt = null
  }

export type ActiveExecution =
  | {
      kind: 'attempt'
      base: CaseResultBase
      attempts: MutableAttempt[]
      number: number
      started: number
      timeoutMs: number
    }
  | {
      kind: 'resource'
      id: number
      name: string
      scope: ResourceScope
      stage: 'before' | 'after' | 'contract'
      started: number
      timeoutMs: number
    }
  | { kind: 'group'; path: number[]; stage: 'before' | 'after' | 'contract'; started: number; timeoutMs: number }

export type ActiveExecution =
  | {
      kind: 'attempt'
      base: CaseResultBase
      attempts: MutableAttempt[]
      number: number
      started: number
      timeoutMs: number
    }
  | {
      kind: 'resource'
      id: number
      name: string
      scope: ResourceScope
      stage: 'before' | 'after' | 'contract'
      started: number
      timeoutMs: number
    }
  | { kind: 'group'; path: number[]; stage: 'before' | 'after' | 'contract'; started: number; timeoutMs: number }

export type Progress =
  | { kind: 'resource'; result: MutableResourceResult }
  | { kind: 'init'; result: MutableRunResult }
  | { kind: 'case'; result: MutableCaseResult }
  | { kind: 'group'; path: number[]; middleware: MutableGroupMiddleware | null }

export type Progress =
  | { kind: 'resource'; result: MutableResourceResult }
  | { kind: 'init'; result: MutableRunResult }
  | { kind: 'case'; result: MutableCaseResult }
  | { kind: 'group'; path: number[]; middleware: MutableGroupMiddleware | null }

export function progressOf(active: ActiveExecution, phase: ExecutionPhase | null, reason: Reason): Progress {
  if (active.kind === 'attempt') {
    const { base, attempts, number, started, timeoutMs } = active
    return {
      kind: 'case',
      result: {
        ...base,
        durationMs: now() - started,
        attempts: [
          ...attempts,
          {
            attempt: number,
            status: reason === 'timeout' ? 'failed' : 'cancelled',
            durationMs: now() - started,
            outcome: null,
            assertions: [],
            failures:
              reason === 'timeout'
                ? [
                    failure(
                      'timeout',
                      required(phase, 'no active phase for progress'),
                      `attempt exceeded ${timeoutMs}ms`,
                      { timeoutMs, cleanup: 'incomplete' },
                    ),
                  ]
                : [],
            cleanup: 'incomplete',
          },
        ],
      },
    }
  }
  if (active.kind === 'resource')
    return {
      kind: 'resource',
      result: {
        id: active.id,
        name: active.name,
        scope: active.scope,
        middleware: {
          status: reason === 'timeout' ? 'failed' : 'cancelled',
          durationMs: now() - active.started,
          cleanup: 'incomplete',
          failures:
            reason === 'timeout'
              ? [
                  {
                    kind: 'timeout',
                    phase: active.stage,
                    timeoutMs: active.timeoutMs,
                    message: `resource ${active.name} exceeded ${active.timeoutMs}ms`,
                  },
                ]
              : [],
        },
      },
    }
  return {
    kind: 'group',
    path: active.path,
    middleware: {
      status: reason === 'timeout' ? 'failed' : 'cancelled',
      durationMs: now() - active.started,
      cleanup: 'incomplete',
      failures:
        reason === 'timeout'
          ? [
              {
                kind: 'timeout',
                phase: active.stage,
                timeoutMs: active.timeoutMs,
                message: `group middleware exceeded ${active.timeoutMs}ms`,
              },
            ]
          : [],
    },
  }
}

