          if (dependency && dependency.scope !== scope)
            throw new TypeError('call reference belongs to another calls definition')
        }
        return new CallDescriptor(scope, ++count, member, args)
      }

export function callRoots(plan: CallPlan): readonly CallDescriptor[] {
  return plan.output instanceof CallDescriptor ? [plan.output] : Object.values(plan.output)
}

export function descriptor(value: Value): CallDescriptor | null {
  const result = v.safeParse(v.instance(CallDescriptor), value)
  return result.success ? result.output : null
}

function outputOf(value: Value): CallPlan['output'] {
  const ref = descriptor(value)
  if (ref) return ref
  const record = objectValue(value)
  const prototype = valueOf(Object.getPrototypeOf(record))
  if ((prototype !== Object.prototype && prototype !== null) || !Reflect.ownKeys(record).length)
    throw new TypeError('calls must return a call reference or a nonempty named record of references')
  return Object.freeze(
    Object.fromEntries(
      Reflect.ownKeys(record).map((key) => {
        if (typeof key !== 'string') throw new TypeError('call result names must be strings')
        return [key, v.parse(v.instance(CallDescriptor), property(record, key))]
      }),
    ),
  )
}

(key) => {
        if (typeof key !== 'string') throw new TypeError('call result names must be strings')
        return [key, v.parse(v.instance(CallDescriptor), property(record, key))]
      }

export function plannedCalls(plan: CallPlan, target: RuntimeTarget): readonly CallDescriptor[] {
  if (plan.target !== target) throw new TypeError('calls definition belongs to another target')
  outputOf(plan.output)
  const complete = new Set<CallDescriptor>(),
    visiting = new Set<CallDescriptor>()
  const ordered: CallDescriptor[] = []
  const visit = (call: CallDescriptor) => {
    if (call.scope !== plan.scope) throw new TypeError('call reference belongs to another calls definition')
    if (
      target.kind === 'relation'
        ? call.member === null || !Object.hasOwn(target.members, call.member)
        : call.member !== null
    )
      throw new TypeError('call is outside the declared target')
    if (complete.has(call)) return
    if (visiting.has(call)) throw new TypeError('cyclic call references')
    visiting.add(call)
    for (const arg of call.args) {
      const dependency = descriptor(arg)
      if (dependency) visit(dependency)
    }
    visiting.delete(call)
    complete.add(call)
    ordered.push(call)
  }
  callRoots(plan).forEach(visit)
  return ordered
}

(call: CallDescriptor) => {
    if (call.scope !== plan.scope) throw new TypeError('call reference belongs to another calls definition')
    if (
      target.kind === 'relation'
        ? call.member === null || !Object.hasOwn(target.members, call.member)
        : call.member !== null
    )
      throw new TypeError('call is outside the declared target')
    if (complete.has(call)) return
    if (visiting.has(call)) throw new TypeError('cyclic call references')
    visiting.add(call)
    for (const arg of call.args) {
      const dependency = descriptor(arg)
      if (dependency) visit(dependency)
    }
    visiting.delete(call)
    complete.add(call)
    ordered.push(call)
  }

export function addCase(data: DefinitionData, item: CaseBlueprint): DefinitionData {
  return { ...data, stage: 'suite', cases: [...data.cases, item] }
}

export function addGroup(
  data: DefinitionData,
  group: {
    name: string | null
    origin: SourceLocation
    middleware: RuntimeMiddleware | null
    children: { origin: SourceLocation; blueprint: RuntimeBlueprint }[]
  },
): DefinitionData {
  const node: RuntimeGroup = { version: 1, kind: 'group', config: {}, steps: [], mocks: [], ...group }
  return { ...data, stage: 'group', groups: [...data.groups, node] }
}

export function callsAllowed(data: CaseData): void {
  if (data.calls.length) throw new TypeError('expectCalls already set')
}

export function caseAllowed(data: DefinitionData): void {
  if (data.stage !== 'target' && data.stage !== 'suite') throw new TypeError('select target before cases')
}

export function caseDone(data: CaseData): true {
  if (!data[doneTag]) throw new TypeError('case must return args and an expectation')
  return true
}

export function caseName(name: Value): string {
  if (typeof name !== 'string') throw new TypeError('case name must be a string')
  return name
}

export function completedCase(
  data: CaseData,
  base: { name: string; mode: RuntimeCase['mode']; origin: SourceLocation; row: CaseBlueprint['row'] },
): RuntimeCase {
  if (!data[doneTag] || !data.args || (!data.expect && !data.calls.length))
    throw new TypeError('case must return args and an expectation')
  return {
    ...base,
    ...(data.resources ? { resources: data.resources } : {}),
    config: data.config,
    mocks: data.mocks,
    args: data.args,
    expect: data.expect,
    calls: data.calls,
  }
}

export function emptyCase(): CaseData {
  return { config: {}, mocks: [], args: null, expect: null, calls: [] }
}

export function emptyDefinition(): DefinitionData {
  return { stage: 'base', config: {}, steps: [], mocks: [], groups: [], cases: [], target: null, name: null }
}

export function groupAllowed(data: DefinitionData): void {
  if (data.stage !== 'base' && data.stage !== 'group') throw new TypeError('group requires a group builder')
}

export function groupArguments(input: readonly Value[]): {
  name: string | null
  middleware: RuntimeMiddleware | null
  children: Value
} {
  const [first, ...rest] = input
  const name = typeof first === 'string' ? first : null
  const args = name === null ? input : rest
  const head = args[0]
  const middleware =
    head !== null && typeof head === 'object' && property(head, middlewareTag) === true ? checkedMiddleware(head) : null
  const children = middleware ? args.slice(1) : args
  if (children.length !== 1) throw new TypeError('group requires completed children')
  return { name, middleware, children: children[0] }
}

export function selectTarget(data: DefinitionData, input: readonly Value[]): DefinitionData {
  if (data.stage !== 'base') throw new TypeError('target already selected')
  const [first, ...rest] = input
  const name = typeof first === 'string' && rest.length ? first : null
  const args = name === null ? input : rest
  const [subject, key] = args
  let target: RuntimeTarget
  if (args.length === 1 && typeof subject === 'function') target = { kind: 'function', fn: functionValue(subject) }
  else if (args.length === 1 && subject && typeof subject === 'object' && property(subject, relationTag) === true)
    target = checkedRelation(subject)
  else if (args.length === 2 && subject && typeof key === 'string')
    target = { kind: 'method', object: objectValue(subject), key, fn: methodValue(subject, key) }
  else throw new TypeError('target requires a function or object method')
  return {
    ...data,
    stage: 'target',
    name:
      name ??
      (target.kind === 'relation'
        ? Object.keys(target.members).join(' / ')
        : target.kind === 'method'
          ? target.key
          : functionValue(target.fn).name || '<anonymous>'),
    target,
  }
}

export function settingAllowed(data: DefinitionData): void {
  if (data.stage === 'group' || data.stage === 'suite')
    throw new TypeError('common settings are fixed after the first group or case')
}

export function toBlueprint(data: DefinitionData): RuntimeBlueprint {
  if (data.stage === 'suite') {
    if (data.name === null || data.target === null) throw new TypeError('test definition is incomplete')
    return {
      ...(data.resources ? { resources: data.resources } : {}),
      version: 1,
      kind: 'test',
      name: data.name,
      target: data.target,
      cases: [...data.cases],
      config: { ...data.config },
      steps: [...data.steps],
      mocks: [...data.mocks],
    }
  }
  if (data.stage === 'group')
    return {
      ...(data.resources ? { resources: data.resources } : {}),
      version: 1,
      kind: 'definition',
      config: { ...data.config },
      steps: [...data.steps],
      mocks: [...data.mocks],
      children: [...data.groups],
    }
  throw new TypeError('test definition is incomplete')
}

export function todoCase(name: string, origin: SourceLocation): RuntimeTodo {
  return { name, mode: 'todo', origin, row: null, config: {} }
}

export function withArgs(data: CaseData, args: RuntimeArgs): CaseData {
  if (data.args && (data.args.kind === 'calls' || args.kind === 'calls'))
    throw new TypeError('args, argsFrom and calls are mutually exclusive')
  return { ...data, args }
}

export function withCalls(data: CaseData, calls: readonly RuntimeCallAssertion[]): CaseData {
  return { ...data, [doneTag]: true, calls: validateCalls(calls) }
}

export function withExpectation(data: CaseData, build: object): CaseData {
  if (data.expect) throw new TypeError('expect already set')
  return { ...data, [doneTag]: true, expect: { kind: 'deferred', build } }
}

export function withMock<T extends { mocks: RuntimeMock[] }>(data: T, mock: RuntimeMock) {
  const mocks = [...data.mocks]
  const index = mocks.findIndex((item) => item.object === mock.object && item.key === mock.key)
  if (index < 0) mocks.push(mock)
  else mocks[index] = mock
  return { ...data, mocks }
}

export function withResource<T extends { resources?: readonly Resource[] }>(data: T, resource: Resource): T {
  return { ...data, resources: checkedResources([...(data.resources ?? []), resource]) }
}

export function withRetry<T extends { config: ExecutionConfig }>(data: T, count: number) {
  return { ...data, config: { ...data.config, retry: retryCount(count) } }
}

export function withStep(data: DefinitionData, step: RuntimeMiddleware): DefinitionData {
  return { ...data, steps: [...data.steps, step] }
}

export function withTimeout<T extends { config: ExecutionConfig }>(data: T, ms: number) {
  return { ...data, config: { ...data.config, timeout: positive(ms, 'timeout') } }
}

export function methodValue<T>(object: T, key: PropertyKey): AnyFn {
  if (object === null || (typeof object !== 'object' && typeof object !== 'function'))
    throw new TypeError('method target must be an object')
  let current: object | null = object
  while (current !== null) {
    const descriptor = Object.getOwnPropertyDescriptor(current, key)
    if (descriptor) {
      if (!('value' in descriptor) || typeof descriptor.value !== 'function')
        throw new TypeError('method target must be a data property containing a function')
      return functionValue(descriptor.value)
    }
    const prototype: Value = valueOf(Object.getPrototypeOf(current))
    current = prototype === null ? null : objectValue(prototype)
  }
  throw new TypeError('method target does not exist')
}

export function plainFields(value: Value): Fields {
  if (value === undefined) return {}
  if (
    value === null ||
    typeof value !== 'object' ||
    Array.isArray(value) ||
    ![Object.prototype, null].some((prototype) => Object.is(prototype, Object.getPrototypeOf(value)))
  ) {
    throw new TypeError('next(fields) requires a plain object')
  }
  return fieldsValue(value)
}

export interface Relation<M extends Record<string, AnyFn> = Record<string, AnyFn>> {
  readonly [relationTag]: true
  readonly kind: 'relation'
  readonly members: Readonly<M>
}

export function checkedRelation(value: object): Relation {
  if (property(value, relationTag) !== true || property(value, 'kind') !== 'relation')
    throw new TypeError('target requires relation()')
  return relationValue(objectValue(property(value, 'members')))
}

export function relation<const M extends Record<string, AnyFn>>(
  members: M & (keyof M extends never ? never : unknown) & Record<Exclude<keyof M, string>, never>,
): Relation<M>
export function relation(members: object): Relation {
  return relationValue(members)
}

function relationValue(members: object): Relation {
  const keys = Reflect.ownKeys(members)
  if (!keys.length || keys.some((key) => typeof key !== 'string' || typeof property(members, key) !== 'function'))
    throw new TypeError('relation requires a nonempty record of named functions')
  return Object.freeze({
    [relationTag]: true as const,
    kind: 'relation' as const,
    members: Object.freeze(Object.fromEntries(keys.map((key) => [key, functionValue(property(members, key))]))),
  })
}

export interface ResourceNext {
  (): Promise<MiddlewareResult<{}>>
  <S extends JsonObject>(fields: S): Promise<MiddlewareResult<S>>
}

export function checkedResources(input: readonly Resource[] | undefined): readonly Resource[] {
  if (input === undefined) return []
  const resources: readonly Resource[] = input
  if (!Array.isArray(input)) throw new TypeError('resource requirements must be an array')
  for (const r of resources) {
    if (!r || r[resourceTag] !== true || !['perRun', 'perWorker'].includes(r.scope) || typeof r.setup !== 'function')
      throw new TypeError('require requires resource()')
    if (r.timeout !== undefined) positive(r.timeout, 'resource timeout')
  }
  return [...new Set(resources)]
}

function cloneJson(value: Value, path: string, ancestors: Set<object>): JsonValue {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return value
  if (typeof value === 'number' && Number.isFinite(value) && !Object.is(value, -0)) return value
  if (typeof value !== 'object' || value === null) throw new TypeError(`resource data at ${path} must be JSON data`)
  if (ancestors.has(value)) throw new TypeError(`resource data at ${path} is cyclic`)
  const prototype = valueOf(Object.getPrototypeOf(value))
  if (
    Array.isArray(value)
      ? !Object.is(prototype, Array.prototype)
      : ![Object.prototype, null].some((p) => Object.is(p, prototype))
  )
    throw new TypeError(`resource data at ${path} must have a plain prototype`)
  ancestors.add(value)
  try {
    const keys = Reflect.ownKeys(value)
    if (Array.isArray(value)) {
      if (keys.length !== value.length + 1)
        throw new TypeError(`resource array at ${path} must be dense without extra properties`)
      const items: JsonValue[] = []
      for (let i = 0; i < value.length; i++)
        items.push(cloneJson(dataProperty(value, String(i), path), `${path}[${i}]`, ancestors))
      return items
    }
    return Object.fromEntries(
      keys.map((key) => {
        if (typeof key !== 'string') throw new TypeError(`resource data at ${path} cannot have symbol keys`)
        return [key, cloneJson(dataProperty(value, key, path), `${path}.${key}`, ancestors)]
      }),
    )
  } finally {
    ancestors.delete(value)
  }
}

