export function diagnostic<T>(value: T): DiagnosticValue {
  const objects = new WeakMap<object, number>()
  const inspected: object[] = []
  const symbols = new Map<symbol, number>()
  let nextId = 1
  function discardSince(start: number) {
    while (inspected.length > start) objects.delete(required(inspected.pop()))
  }
  function visit<T>(value: T, depth = 0): DiagnosticValue {
    const start = inspected.length
    try {
      const result = inspectValue(value, depth)
      if (result.kind === 'omitted') discardSince(start)
      return result
    } catch (error) {
      discardSince(start)
      // Proxy traps can throw even when descriptors are read without invoking getters.
      let reason = 'inspection failed'
      try {
        const message: unknown =
          typeof error === 'object' && error !== null ? Object.getOwnPropertyDescriptor(error, 'message')?.value : error
        if (typeof message === 'string') reason += `: ${message}`
      } catch {
        reason += '; thrown value is also uninspectable'
      }
      return { kind: 'omitted', reason }
    }
  }
  function inspectValue<T>(value: T, depth: number): DiagnosticValue {
    const input = valueOf(value)
    if (input === undefined) return { kind: 'undefined' }
    if (input === null) return { kind: 'null' }
    if (typeof input === 'boolean') return { kind: 'boolean', value: input }
    if (typeof input === 'string') return { kind: 'string', value: input }
    if (typeof input === 'number')
      return {
        kind: 'number',
        value: Object.is(input, -0)
          ? '-0'
          : Number.isNaN(input)
            ? 'NaN'
            : input === Infinity
              ? 'Infinity'
              : input === -Infinity
                ? '-Infinity'
                : input,
      }
    if (typeof input === 'bigint') return { kind: 'bigint', value: String(input) }
    if (typeof input === 'symbol') return keyOf(input, symbols)
    if (objects.has(input)) return { kind: 'reference', id: required(objects.get(input)) }
    const id = nextId++
    objects.set(input, id)
    inspected.push(input)
    if (typeof input === 'function') {
      const name: unknown = Object.getOwnPropertyDescriptor(input, 'name')?.value
      return { kind: 'function', id, name: typeof name === 'string' ? name : '<accessor>' }
    }
    if (input instanceof Date)
      return {
        kind: 'date',
        id,
        value: Number.isNaN(Date.prototype.getTime.call(input)) ? null : Date.prototype.toISOString.call(input),
      }
    if (input instanceof RegExp) {
      const get = (name: string) =>
        invoke(required(required(Object.getOwnPropertyDescriptor(RegExp.prototype, name)).get), input, [])
      const flags = [
        ['hasIndices', 'd'],
        ['global', 'g'],
        ['ignoreCase', 'i'],
        ['multiline', 'm'],
        ['dotAll', 's'],
        ['unicode', 'u'],
        ['unicodeSets', 'v'],
        ['sticky', 'y'],
      ]
        .filter(([name]) => get(name))
        .map(([, letter]) => letter)
        .join('')
      return { kind: 'regexp', id, source: String(get('source')), flags }
    }
    if (depth >= 8) return { kind: 'omitted', reason: 'depth limit' }
    if (input instanceof Map)
      return {
        kind: 'map',
        id,
        entries: [...Map.prototype.entries.call(input)].map(([k, v]) => [visit(k, depth + 1), visit(v, depth + 1)]),
      }
    if (input instanceof Set)
      return { kind: 'set', id, values: [...Set.prototype.values.call(input)].map((v) => visit(v, depth + 1)) }
    const properties: DiagnosticProperty[] = []
    const omitted: string[] = []
    if (input instanceof Error)
      for (const key of ['name', 'message', 'cause', 'stack']) {
        let source: object | null = input,
          desc
        while (source && !desc) {
          desc = Object.getOwnPropertyDescriptor(source, key)
          const prototype: Value = valueOf(Object.getPrototypeOf(source))
          source = prototype === null ? null : objectValue(prototype)
        }
        if (desc)
          properties.push({
            key: { kind: 'string', value: key },
            value:
              'value' in desc ? visit(desc.value, depth + 1) : { kind: 'accessor', get: !!desc.get, set: !!desc.set },
          })
      }
    for (const key of Reflect.ownKeys(input)) {
      const desc = Object.getOwnPropertyDescriptor(input, key)
      if (!desc?.enumerable) continue
      if (Array.isArray(input) && typeof key === 'string' && /^(0|[1-9]\d*)$/.test(key)) continue
      if (input instanceof Error && ['name', 'message', 'cause', 'stack'].includes(String(key))) continue
      if (properties.length >= 100) {
        omitted.push(String(key))
        continue
      }
      properties.push({
        key: keyOf(key, symbols),
        value: 'value' in desc ? visit(desc.value, depth + 1) : { kind: 'accessor', get: !!desc.get, set: !!desc.set },
      })
    }
    if (Array.isArray(input)) {
      const items = Array.from({ length: input.length }, (_, index): DiagnosticValue => {
        const desc = Object.getOwnPropertyDescriptor(input, index)
        return !desc
          ? { kind: 'hole' }
          : 'value' in desc
            ? visit(desc.value, depth + 1)
            : { kind: 'accessor', get: !!desc.get, set: !!desc.set }
      })
      return { kind: 'array', id, items, properties }
    }
    let type = 'Object'
    const ctor = valueOf(
      Object.getOwnPropertyDescriptor(valueOf(Object.getPrototypeOf(input)) ?? {}, 'constructor')?.value,
    )
    if (typeof ctor === 'function')
      type = String(valueOf(Object.getOwnPropertyDescriptor(ctor, 'name')?.value) || 'Object')
    return { kind: 'object', id, type, properties, omitted }
  }
  return visit(value)
}

function discardSince(start: number) {
    while (inspected.length > start) objects.delete(required(inspected.pop()))
  }

function inspectValue<T>(value: T, depth: number): DiagnosticValue {
    const input = valueOf(value)
    if (input === undefined) return { kind: 'undefined' }
    if (input === null) return { kind: 'null' }
    if (typeof input === 'boolean') return { kind: 'boolean', value: input }
    if (typeof input === 'string') return { kind: 'string', value: input }
    if (typeof input === 'number')
      return {
        kind: 'number',
        value: Object.is(input, -0)
          ? '-0'
          : Number.isNaN(input)
            ? 'NaN'
            : input === Infinity
              ? 'Infinity'
              : input === -Infinity
                ? '-Infinity'
                : input,
      }
    if (typeof input === 'bigint') return { kind: 'bigint', value: String(input) }
    if (typeof input === 'symbol') return keyOf(input, symbols)
    if (objects.has(input)) return { kind: 'reference', id: required(objects.get(input)) }
    const id = nextId++
    objects.set(input, id)
    inspected.push(input)
    if (typeof input === 'function') {
      const name: unknown = Object.getOwnPropertyDescriptor(input, 'name')?.value
      return { kind: 'function', id, name: typeof name === 'string' ? name : '<accessor>' }
    }
    if (input instanceof Date)
      return {
        kind: 'date',
        id,
        value: Number.isNaN(Date.prototype.getTime.call(input)) ? null : Date.prototype.toISOString.call(input),
      }
    if (input instanceof RegExp) {
      const get = (name: string) =>
        invoke(required(required(Object.getOwnPropertyDescriptor(RegExp.prototype, name)).get), input, [])
      const flags = [
        ['hasIndices', 'd'],
        ['global', 'g'],
        ['ignoreCase', 'i'],
        ['multiline', 'm'],
        ['dotAll', 's'],
        ['unicode', 'u'],
        ['unicodeSets', 'v'],
        ['sticky', 'y'],
      ]
        .filter(([name]) => get(name))
        .map(([, letter]) => letter)
        .join('')
      return { kind: 'regexp', id, source: String(get('source')), flags }
    }
    if (depth >= 8) return { kind: 'omitted', reason: 'depth limit' }
    if (input instanceof Map)
      return {
        kind: 'map',
        id,
        entries: [...Map.prototype.entries.call(input)].map(([k, v]) => [visit(k, depth + 1), visit(v, depth + 1)]),
      }
    if (input instanceof Set)
      return { kind: 'set', id, values: [...Set.prototype.values.call(input)].map((v) => visit(v, depth + 1)) }
    const properties: DiagnosticProperty[] = []
    const omitted: string[] = []
    if (input instanceof Error)
      for (const key of ['name', 'message', 'cause', 'stack']) {
        let source: object | null = input,
          desc
        while (source && !desc) {
          desc = Object.getOwnPropertyDescriptor(source, key)
          const prototype: Value = valueOf(Object.getPrototypeOf(source))
          source = prototype === null ? null : objectValue(prototype)
        }
        if (desc)
          properties.push({
            key: { kind: 'string', value: key },
            value:
              'value' in desc ? visit(desc.value, depth + 1) : { kind: 'accessor', get: !!desc.get, set: !!desc.set },
          })
      }
    for (const key of Reflect.ownKeys(input)) {
      const desc = Object.getOwnPropertyDescriptor(input, key)
      if (!desc?.enumerable) continue
      if (Array.isArray(input) && typeof key === 'string' && /^(0|[1-9]\d*)$/.test(key)) continue
      if (input instanceof Error && ['name', 'message', 'cause', 'stack'].includes(String(key))) continue
      if (properties.length >= 100) {
        omitted.push(String(key))
        continue
      }
      properties.push({
        key: keyOf(key, symbols),
        value: 'value' in desc ? visit(desc.value, depth + 1) : { kind: 'accessor', get: !!desc.get, set: !!desc.set },
      })
    }
    if (Array.isArray(input)) {
      const items = Array.from({ length: input.length }, (_, index): DiagnosticValue => {
        const desc = Object.getOwnPropertyDescriptor(input, index)
        return !desc
          ? { kind: 'hole' }
          : 'value' in desc
            ? visit(desc.value, depth + 1)
            : { kind: 'accessor', get: !!desc.get, set: !!desc.set }
      })
      return { kind: 'array', id, items, properties }
    }
    let type = 'Object'
    const ctor = valueOf(
      Object.getOwnPropertyDescriptor(valueOf(Object.getPrototypeOf(input)) ?? {}, 'constructor')?.value,
    )
    if (typeof ctor === 'function')
      type = String(valueOf(Object.getOwnPropertyDescriptor(ctor, 'name')?.value) || 'Object')
    return { kind: 'object', id, type, properties, omitted }
  }

(_, index): DiagnosticValue => {
        const desc = Object.getOwnPropertyDescriptor(input, index)
        return !desc
          ? { kind: 'hole' }
          : 'value' in desc
            ? visit(desc.value, depth + 1)
            : { kind: 'accessor', get: !!desc.get, set: !!desc.set }
      }

function visit<T>(value: T, depth = 0): DiagnosticValue {
    const start = inspected.length
    try {
      const result = inspectValue(value, depth)
      if (result.kind === 'omitted') discardSince(start)
      return result
    } catch (error) {
      discardSince(start)
      // Proxy traps can throw even when descriptors are read without invoking getters.
      let reason = 'inspection failed'
      try {
        const message: unknown =
          typeof error === 'object' && error !== null ? Object.getOwnPropertyDescriptor(error, 'message')?.value : error
        if (typeof message === 'string') reason += `: ${message}`
      } catch {
        reason += '; thrown value is also uninspectable'
      }
      return { kind: 'omitted', reason }
    }
  }

function keyOf(key: string | symbol, symbols: Map<symbol, number>): DiagnosticKey {
  if (typeof key === 'string') return { kind: 'string', value: key }
  if (!symbols.has(key)) symbols.set(key, symbols.size + 1)
  return { kind: 'symbol', id: required(symbols.get(key)), description: key.description ?? null }
}

function finalizeAttempt(input: MutableAttempt): AttemptResult {
  const { status, failures, assertions, cleanup, ...base } = input
  if (status === 'failed') return { ...base, status, failures: nonempty(failures), assertions, cleanup }
  if (failures.length) throw new TypeError('successful or cancelled attempts cannot contain failures')
  if (status === 'passed') {
    if (cleanup !== 'complete') throw new TypeError('passed attempts require complete cleanup')
    const passed = assertions.map((a) => {
      if (a.status !== 'passed') throw new TypeError('passed attempts require passed assertions')
      return a
    })
    return { ...base, status, failures: [], assertions: passed, cleanup }
  }
  const cancelled = assertions.map((a) => {
    if (a.status === 'failed') throw new TypeError('cancelled attempts cannot contain failed assertions')
    return a
  })
  return { ...base, status, failures: [], assertions: cancelled, cleanup }
}

(a) => {
      if (a.status !== 'passed') throw new TypeError('passed attempts require passed assertions')
      return a
    }

(a) => {
    if (a.status === 'failed') throw new TypeError('cancelled attempts cannot contain failed assertions')
    return a
  }

function finalizeCase(input: MutableCaseResult): CaseResult {
  const { attempts, notRun, ...base } = input
  if (notRun !== undefined) {
    if (attempts.length) throw new TypeError('unexecuted cases cannot contain attempts')
    return { ...base, notRun, attempts: [] }
  }
  const last = finalizeAttempt(required(attempts.at(-1), 'executed cases require an attempt'))
  const retries: (FailedAttemptResult & { readonly cleanup: 'complete' })[] = attempts.slice(0, -1).map((input) => {
    const value = finalizeAttempt(input)
    if (value.status !== 'failed' || value.cleanup !== 'complete')
      throw new TypeError('retries require failed attempts with complete cleanup')
    return { ...value, cleanup: value.cleanup }
  })
  if (last.status === 'passed') return { ...base, attempts: [...retries, last] }
  if (last.status === 'failed') return { ...base, attempts: [...retries, last] }
  return { ...base, attempts: [...retries, last] }
}

(input) => {
    const value = finalizeAttempt(input)
    if (value.status !== 'failed' || value.cleanup !== 'complete')
      throw new TypeError('retries require failed attempts with complete cleanup')
    return { ...value, cleanup: value.cleanup }
  }

function finalizeMiddleware(input: MutableGroupMiddleware): GroupMiddlewareResult {
  const { status, durationMs, failures, cleanup } = input
  if (status === 'failed') return { status, durationMs, failures: nonempty(failures), cleanup }
  if (failures.length) throw new TypeError('successful or unexecuted middleware cannot contain failures')
  if (status === 'cancelled') return { status, durationMs, failures: [], cleanup }
  if (cleanup !== 'complete') throw new TypeError('passed or unexecuted middleware requires complete cleanup')
  if (status === 'passed') return { status, durationMs, failures: [], cleanup }
  if (durationMs !== 0) throw new TypeError('unexecuted middleware must have zero duration')
  return { status, durationMs, failures: [], cleanup, reason: required(input.reason) }
}

function finalizeNode(input: MutableNodeResult): TestResult | GroupResult {
  if (input.kind === 'test') return { ...input, cases: input.cases.map(finalizeCase) }
  return {
    ...input,
    middleware: input.middleware ? finalizeMiddleware(input.middleware) : null,
    children: input.children.map((entry) => ({ ...entry, result: finalizeNode(entry.result) })),
  }
}

export function finalizeRun(input: MutableRunResult): RunResult {
  const tests = input.tests.map(finalizeNode)
  const resources = input.resources
    ? { resources: input.resources.map((r) => ({ ...r, middleware: finalizeMiddleware(r.middleware) })) }
    : {}
  if (input.status === 'passed') {
    if (input.reason !== 'completed') throw new TypeError('passed runs must complete')
    return { ...resources, version: 1, status: 'passed', reason: 'completed', tests }
  }
  if (input.status === 'cancelled') {
    if (input.reason !== 'interrupted') throw new TypeError('cancelled runs must be interrupted')
    return { ...resources, version: 1, status: 'cancelled', reason: 'interrupted', tests }
  }
  return { ...resources, version: 1, status: 'failed', reason: input.reason, tests }
}

