resolve(specifier: string, parentURL: string): string | null {
    const entry = this.#configFor(parentURL)
    if (!entry) return null
    for (const candidate of aliasCandidates(entry, specifier))
      for (const file of extensions(candidate)) if (existsSync(file)) return file
    return null
  }

function aliasCandidates(entry: ConfigEntry, specifier: string): string[] {
  const options = entry.config.compilerOptions ?? {}
  const base = resolvePath(entry.directory, options.baseUrl ?? '.')
  const matches: string[] = []
  for (const [pattern, replacements] of Object.entries(options.paths ?? {})) {
    const star = pattern.indexOf('*')
    const prefix = star < 0 ? pattern : pattern.slice(0, star)
    const suffix = star < 0 ? '' : pattern.slice(star + 1)
    if (!specifier.startsWith(prefix) || !specifier.endsWith(suffix)) continue
    if (star < 0 && specifier !== pattern) continue
    const captured = specifier.slice(prefix.length, specifier.length - suffix.length)
    for (const replacement of replacements) matches.push(resolvePath(base, replacement.replace('*', captured)))
  }
  return matches
}

function extensions(file: string) {
  if (extname(file) === '.js') return [file.slice(0, -3) + '.ts', file.slice(0, -3) + '.mts']
  if (!extname(file)) return [file + '.ts', file + '.mts', file + '.js', file + '/index.ts', file + '/index.js']
  return [file]
}

function jsonc(text: string): Tsconfig {
  let clean = '',
    quote = false,
    escaped = false,
    line = false,
    block = false
  for (let i = 0; i < text.length; i++) {
    const char = text[i],
      next = text[i + 1]
    if (line) {
      if (char === '\n') {
        line = false
        clean += char
      }
      continue
    }
    if (block) {
      if (char === '*' && next === '/') {
        block = false
        i++
      }
      continue
    }
    if (quote) {
      clean += char
      if (escaped) escaped = false
      else if (char === '\\') escaped = true
      else if (char === '"') quote = false
      continue
    }
    if (char === '"') {
      quote = true
      clean += char
      continue
    }
    if (char === '/' && next === '/') {
      line = true
      i++
      continue
    }
    if (char === '/' && next === '*') {
      block = true
      i++
      continue
    }
    clean += char
  }
  return v.parse(
    v.object({
      compilerOptions: v.optional(
        v.object({ baseUrl: v.optional(v.string()), paths: v.optional(v.record(v.string(), v.array(v.string()))) }),
      ),
    }),
    JSON.parse(clean.replace(/,\s*([}\]])/g, '$1')),
  )
}

export class FacadeRunner {
  readonly #inner: ModuleRunner
  #closing: Promise<void> | undefined

  constructor(facades: ModuleFacades, evaluator: FacadeEvaluator, transport: ModuleTransport) {
    const inner = new ModuleRunner(
      {
        hmr: false,
        transport: {
          async invoke(payload) {
            if (payload.type !== 'custom' || payload.event !== 'vite:invoke')
              throw new Error('unexpected module transport payload')
            const data = v.parse(
              v.object({ name: v.string(), data: v.array(v.union([v.string(), v.undefined(), v.looseObject({})])) }),
              payload.data,
            )
            return { result: await transport.invoke(data.name, data.data) }
          },
        },
      },
      evaluator,
    )
    this.#inner = inner
    const directRequest = functionValue(property(ModuleRunner.prototype, 'directRequest'))
    Reflect.defineProperty(inner, 'directRequest', {
      async value(url: string, module: EvaluatedModuleNode, callstack: string[]): Promise<Namespace> {
        const original = valueOf(await Promise.resolve(invokeFunction(directRequest, inner, [url, module, callstack])))
        const facade = facades.view(module.id, original)
        module.exports = facade
        return facade
      },
    })
    const processImport = functionValue(property(ModuleRunner.prototype, 'processImport'))
    Reflect.defineProperty(inner, 'processImport', {
      value(exports: Namespace, result: ResolvedResult, metadata?: SSRImportMetadata) {
        if (!metadata?.isDynamicImport)
          for (const name of metadata?.importedNames ?? []) {
            if (!(name in exports))
              throw new SyntaxError(`The requested module '${result.url}' does not provide an export named '${name}'`)
          }
        return objectValue(invokeFunction(processImport, inner, [exports, result, metadata]))
      },
    })
  }

  import(url: string): Promise<Namespace> {
    return this.#inner.import<Namespace>(url)
  }

  /** 二重に閉じても同じ約束を返す。 */
  close(): Promise<void> {
    this.#closing ??= this.#inner.close()
    return this.#closing
  }
}

