interface ShutdownPolicy {
  graceMs: number
  reporter: string | undefined
}

class ShutdownTimers {
  #loading: ReturnType<typeof setTimeout> | undefined
  #deadline: ReturnType<typeof setTimeout> | undefined
  #grace: ReturnType<typeof setTimeout> | undefined

  restartLoading(timeoutMs: number, onExpire: () => void): void {
    clearTimeout(this.#loading)
    this.#loading = setTimeout(onExpire, timeoutMs)
  }

  clearLoading(): void {
    clearTimeout(this.#loading)
    this.#loading = undefined
  }

  restartDeadline(timeoutMs: number, onExpire: () => void): void {
    clearTimeout(this.#deadline)
    this.#deadline = setTimeout(onExpire, timeoutMs)
  }

  clearDeadline(): void {
    clearTimeout(this.#deadline)
    this.#deadline = undefined
  }

  startGrace(graceMs: number, onExpire: () => void): void {
    if (this.#grace) return
    this.#grace = setTimeout(onExpire, graceMs)
  }

  clearAll(): void {
    this.clearLoading()
    this.clearDeadline()
    clearTimeout(this.#grace)
    this.#grace = undefined
  }
}

clearAll(): void {
    this.clearLoading()
    this.clearDeadline()
    clearTimeout(this.#grace)
    this.#grace = undefined
  }

restartDeadline(timeoutMs: number, onExpire: () => void): void {
    clearTimeout(this.#deadline)
    this.#deadline = setTimeout(onExpire, timeoutMs)
  }

restartLoading(timeoutMs: number, onExpire: () => void): void {
    clearTimeout(this.#loading)
    this.#loading = setTimeout(onExpire, timeoutMs)
  }

startGrace(graceMs: number, onExpire: () => void): void {
    if (this.#grace) return
    this.#grace = setTimeout(onExpire, graceMs)
  }

function exitCode(phase: SupervisorPhase, code: number): number {
  return phase.kind === 'interrupted' ? 130 : code
}

export function parseArgs(argv: string[]) {
  const options: CliOptions = {},
    files: string[] = []
  const mapped: Record<string, 'filter' | 'reporter' | 'config' | 'collectionTimeout' | 'shutdownGrace' | 'projects'> =
    {
      '-t': 'filter',
      '--filter': 'filter',
      '-r': 'reporter',
      '--reporter': 'reporter',
      '-c': 'config',
      '--config': 'config',
      '--project': 'projects',
      '--collection-timeout': 'collectionTimeout',
      '--shutdown-grace': 'shutdownGrace',
    }
  for (let i = 0; i < argv.length; i++) {
    const word = argv[i]
    if (Object.hasOwn(mapped, word)) {
      const value = argv[++i]
      if (!value || value.startsWith('-')) throw new TypeError(`${word} requires a value`)
      const key = mapped[word]
      if (key === 'collectionTimeout' || key === 'shutdownGrace') options[key] = Number(value)
      else if (key === 'projects') (options.projects ??= []).push(value)
      else options[key] = value
    } else if (word === '--ci') options.ci = true
    else if (word === '--fail-on-flaky') options.failOnFlaky = true
    else if (word === '--no-color') options.noColor = true
    else if (word === '--help' || word === '-h') options.help = true
    else if (word === '--version' || word === '-v') options.version = true
    else if (word.startsWith('-')) throw new TypeError(`unknown option: ${word}`)
    else files.push(word)
  }
  if (options.projects?.length && files.length) throw new TypeError('--project cannot be combined with files')
  return { options, files }
}

