interface ErrorShape {
  readonly name: string
  readonly message: string
  readonly cause: DiagnosticValue | null
}

function errorShape(value: DiagnosticValue): ErrorShape | null {
  if (value.kind !== 'object' || value.properties.length < 2) return null
  const [name, message] = value.properties
  if (name.key.kind !== 'string' || name.key.value !== 'name' || name.value.kind !== 'string') return null
  if (message.key.kind !== 'string' || message.key.value !== 'message' || message.value.kind !== 'string') return null
  if (!namedProperty(value.properties, 'stack')) return null
  return { name: name.value.value, message: message.value.value, cause: namedProperty(value.properties, 'cause') }
}

function formatError(shape: ErrorShape): string {
  const headline = shape.message ? `${shape.name}: ${shape.message}` : shape.name
  return shape.cause === null ? headline : `${headline} (cause: ${formatValue(shape.cause)})`
}

function formatProperty(property: DiagnosticProperty): string {
  const key = property.key.kind === 'string' ? property.key.value : formatValue(property.key)
  return `${key}: ${formatValue(property.value)}`
}

function namedProperty(properties: readonly DiagnosticProperty[], key: string): DiagnosticValue | null {
  const found = properties.find((property) => property.key.kind === 'string' && property.key.value === key)
  return found ? found.value : null
}

export function formatJson(result: MutableRunResult): string {
  return JSON.stringify(result) + '\n'
}

function formatFailure(item: MutableCaseResult, depth: number, groupOrigins: SourceLocation[]) {
  const out: string[] = [],
    pad = '  '.repeat(depth)
  if (item.row) out.push(`${pad}row ${item.row.index + 1}: ${formatValue(item.row.value)}`)
  for (const origin of groupOrigins)
    out.push(`${pad}group: ${relative(process.cwd(), origin.file)}:${origin.line}:${origin.column}`)
  for (const attempt of item.attempts)
    for (const issue of attempt.failures) {
      const ref = 'assertion' in issue ? issue.assertion : undefined
      const label = ref
        ? `${ref.source === 'expectCalls' ? `call(${ref.key})` : ref.subject}.${'negated' in ref && ref.negated ? 'not.' : ''}${ref.matcher}`
        : issue.message
      out.push(`${pad}${label}`)
      if ('expected' in issue) out.push(`${pad}  expected: ${formatValue(issue.expected)}`)
      if ('actual' in issue) out.push(`${pad}  actual:   ${formatValue(issue.actual)}`)
      if ('timeoutMs' in issue)
        out.push(`${pad}  timeout: ${issue.timeoutMs}ms (${issue.phase}${issue.stage ? ` ${issue.stage}` : ''})`)
      if ('cause' in issue) out.push(`${pad}  cause:   ${formatValue(issue.cause)}`)
    }
  return out
}

export function formatNode(node: MutableNodeResult, depth = 0, groupOrigins: SourceLocation[] = []): string[] {
  const lines: string[] = [],
    pad = '  '.repeat(depth)
  if (node.kind === 'group') {
    if (node.name !== null) lines.push(`${pad}${node.name}`)
    if (node.middleware?.status === 'failed')
      for (const issue of node.middleware.failures) {
        lines.push(
          `${pad}  ✗ group middleware: ${issue.message}  ${relative(process.cwd(), node.origin.file)}:${node.origin.line}:${node.origin.column}`,
        )
        if ('cause' in issue) lines.push(`${pad}    cause: ${formatValue(issue.cause)}`)
        if ('timeoutMs' in issue) lines.push(`${pad}    timeout: ${issue.timeoutMs}ms (${issue.phase})`)
      }
    for (const entry of node.children)
      lines.push(...formatNode(entry.result, depth + (node.name === null ? 0 : 1), [...groupOrigins, entry.origin]))
  } else {
    lines.push(`${pad}${node.name}`)
    for (const item of node.cases) {
      const last = item.attempts.at(-1)
      const label =
        item.notRun === 'todo'
          ? '○'
          : item.notRun === 'skipped'
            ? '−'
            : item.notRun === 'cancelled'
              ? '!'
              : last?.status === 'passed'
                ? item.attempts.length > 1
                  ? '⚠'
                  : '✓'
                : last?.status === 'cancelled'
                  ? '!'
                  : '✗'
      const source =
        label === '✗' ? `  ${relative(process.cwd(), item.origin.file)}:${item.origin.line}:${item.origin.column}` : ''
      lines.push(`${pad}  ${label} ${item.name}${source}`)
      if (label === '✗' || label === '⚠') lines.push(...formatFailure(item, depth + 2, groupOrigins))
    }
  }
  return lines
}

export function formatResources(resources: readonly MutableResourceResult[] = []): string[] {
  return resources.flatMap((r) =>
    r.middleware.status === 'failed'
      ? r.middleware.failures.flatMap((issue) => [
          `✗ resource ${r.name} (${r.scope}): ${issue.message}`,
          ...('cause' in issue ? [`  cause: ${formatValue(issue.cause)}`] : []),
          ...('timeoutMs' in issue ? [`  timeout: ${issue.timeoutMs}ms (${issue.phase})`] : []),
        ])
      : [],
  )
}

export class CaseBuilder<F extends AnyFn, C> {
  readonly #data: CaseData
  readonly #target: RuntimeTarget
  constructor(data: CaseData, target: RuntimeTarget) {
    this.#data = data
    this.#target = target
  }
  get [doneTag](): true {
    return caseDone(this.#data)
  }
  // 呼び出し元のチェーンは別クラスで #data を読めないため、完成検査と取り出しをここに置く。
  completed(
    base: {
      name: string
      mode: RuntimeCase['mode']
      origin: SourceLocation
      row: CaseBlueprint['row']
    },
    target: RuntimeTarget,
  ): RuntimeCase {
    if (this.#data.args?.kind === 'calls' && this.#data.args.target !== target)
      throw new TypeError('calls definition belongs to another target')
    return completedCase(this.#data, base)
  }
  #next(data: CaseData): CaseBuilder<F, C> {
    return new CaseBuilder(data, this.#target)
  }
  timeout(ms: number) {
    return this.#next(withTimeout(this.#data, ms))
  }
  retry(count: number) {
    return this.#next(withRetry(this.#data, count))
  }
  mock<O extends object, K extends FnKeys<O>>(object: O, key: K, def: MockDef<MethodOf<O, K>>): CaseBuilder<F, C> {
    return this.#next(withMock(this.#data, createMock(object, key, def)))
  }
  require<T extends Resource>(r: T): ItBuilder<F, ExtendContext<ResourceFields<T>, C>>
  require(r: Resource): object {
    return this.#next(withResource(this.#data, r))
  }
  args(...args: Parameters<F>): ItArgs<F, C> {
    if (this.#target.kind === 'relation') throw new TypeError('relation cases require calls()')
    return this.#next(withArgs(this.#data, { kind: 'value', value: arrayValue(args) }))
  }
  argsFrom(build: (ctx: Readonly<C>) => Parameters<F>): ItArgs<F, C> {
    if (this.#target.kind === 'relation') throw new TypeError('relation cases require calls()')
    return this.#next(withArgs(this.#data, { kind: 'from-context', build }))
  }
  calls<const O extends CallOutput>(
    build: (c: InvocationBuilder<F>) => O & NonemptyOutput<O>,
  ): ItInvocations<CallsResult<O>, C>
  calls(build: object): object {
    if (this.#data.args) throw new TypeError('args, argsFrom and calls are mutually exclusive')
    return this.#next(withArgs(this.#data, buildCallPlan(this.#target, build)))
  }
  expect(build: (e: Expect<F, C>) => Assertions): ItExpected<C> {
    return this.#next(
      withExpectation(this.#data, (ctx: Fields) =>
        invoke(build, undefined, [{ result: valueAssertions('result'), error: valueAssertions('error'), ctx }]),
      ),
    )
  }
  expectCalls(build: CallsBuilder<C>): ItCalls<F, C> {
    callsAllowed(this.#data)
    const calls = arrayValue(invoke(build, undefined, [callBuilder])).map(checkedCall)
    return this.#next(withCalls(this.#data, calls))
  }
}

#next(data: CaseData): CaseBuilder<F, C> {
    return new CaseBuilder(data, this.#target)
  }

args(...args: Parameters<F>): ItArgs<F, C> {
    if (this.#target.kind === 'relation') throw new TypeError('relation cases require calls()')
    return this.#next(withArgs(this.#data, { kind: 'value', value: arrayValue(args) }))
