export function isDefinition<T>(value: T): boolean {
  return value instanceof DefinitionBuilder && value[definitionTag] === true
}

export function middleware<C, S extends object>(
  fn: MiddlewareFn<C, S>,
  options: MiddlewareOptions = {},
): Middleware<C, S> {
  if (typeof fn !== 'function') throw new TypeError('middleware requires a function')
  const timeout = options.timeout === undefined ? undefined : positive(options.timeout, 'middleware timeout')
  const value: Middleware<C, S> = { [middlewareTag]: true, kind: 'middleware', run: fn, timeout }
  return Object.freeze(value)
}

export function createRegisterTest(location: () => SourceLocation, record: (event: CollectionEvent) => void) {
  return function registerTest(root: TestDefinition<{}>): void {
    const definition = v.parse(v.instance(DefinitionBuilder), root)
    if (!isDefinition(definition)) throw new TypeError('registerTest requires a completed test definition')
    record({ kind: 'registered', definition, origin: location() })
  }
}

function registerTest(root: TestDefinition<{}>): void {
    const definition = v.parse(v.instance(DefinitionBuilder), root)
    if (!isDefinition(definition)) throw new TypeError('registerTest requires a completed test definition')
    record({ kind: 'registered', definition, origin: location() })
  }

export function resource<
  const D extends readonly Resource[] = readonly [],
  S extends JsonObject = JsonObject,
  Scope extends ResourceScope = ResourceScope,
>(options: {
  readonly name?: string
  readonly scope: Scope
  readonly require?: D
  readonly timeout?: number
  readonly setup: (ctx: Readonly<ResourceContext<D>>, next: ResourceNext) => Promise<MiddlewareResult<S>>
}): Resource<S, Scope> {
  if (!options || !['perRun', 'perWorker'].includes(options.scope))
    throw new TypeError('resource scope must be perRun or perWorker')
  if (typeof options.setup !== 'function') throw new TypeError('resource setup must be a function')
  if (options.name !== undefined && typeof options.name !== 'string')
    throw new TypeError('resource name must be a string')
  const value: Resource<S, Scope> = {
    [resourceTag]: true,
    name: options.name ?? options.setup.name ?? '<resource>',
    scope: options.scope,
    require: Object.freeze(checkedResources(options.require)),
    timeout: options.timeout === undefined ? undefined : positive(options.timeout, 'resource timeout'),
    setup: options.setup,
  }
  return Object.freeze(value)
}

export interface RunInput extends RunSettings, RunListeners {
  readonly signal?: AbortSignal
}

export function collectBlueprints(input: Value): RuntimeBlueprint[] {
  const definitions = Array.isArray(input) ? arrayValue(input) : [input]
  if (!definitions.length || definitions.some((x) => !isDefinition(x)))
    throw new TypeError('run requires completed definitions')
  return validatedBlueprints(definitions.map((def: Value) => v.parse(v.instance(DefinitionBuilder), def)))
}

export function createRun(comparison: () => Promise<ConfigClass<Comparison>>) {
  return function run(input: TestDefinition | readonly TestDefinition[], options: RunOptions = {}): Promise<RunResult> {
    const received: RunInput = options
    // 錠はscopeを立てるより先に取る。収集の途中で始まったrunも重なりとして弾く。
    return runExclusively(async () => {
      const scope = await createApp([]).createRuntime({ configs: [await comparison(), LocalExecutor] })
      try {
        // 受け取り手は呼び出しの引数で決まる。1回ぶんの通知の宛先として組み立てて渡す。
        const events = new ListenerEvents(received, await scope.get(RunSnapshot))
        const walker = await scope.get(RunWalker)
        const execution = await (await scope.get(LocalExecutor)).start(events)
        try {
          return finalizeRun(
            await walker.run(
              execution,
              () => createPlan(collectBlueprints(input), received),
              received,
              events,
              received.signal,
            ),
          )
        } finally {
          await execution.close()
        }
      } finally {
        await scope.shutdown()
      }
    })
  }
}

